package com.example.hiringsys.mapper; import com.example.hiringsys.dto.request.CargoRequest; import com.example.hiringsys.dto.response.CargoResponse; import com.example.hiringsys.entity.Cargo; import org.springframework.stereotype.Component;
@Component public class CargoMapper {public Cargo toEntity(CargoRequest r){Cargo c=new Cargo();c.setNome(r.nome());return c;}public CargoResponse toResponse(Cargo c){return new CargoResponse(c.getId(),c.getNome());}}
